export function matrizSaeb(componente: string, ano: string): MatrizSaeb | null {
    return MATRIZES_SAEB.find((m) => m.componente === componente && m.ano === ano) ?? null;
}

/** As habilidades do Saeb pelos códigos (o ano sai do próprio código: 5L2.4 → 5º ano). Serve para faixas como "1º ao 5º ano". */
export function saebPorCodigos(componente: string, codigos: string[]): DescritorSaeb[] {
    const areaDe = (c: string) =>
        c.startsWith("CN-") ? "Ciências" : c.startsWith("CH-") ? "Ciências Humanas" : componente;
    return codigos
        .map((c) => matrizSaeb(areaDe(c), `${/\d/.exec(c)?.[0]}º ano`)?.descritores.find((x) => x.codigo === c))
        .filter((x): x is DescritorSaeb => Boolean(x));
}
